/* === Step 5: 变量读取 === */

async function captureState() {
    const allVars = typeof getAllVariables === 'function' ? getAllVariables() : {};
    const rawData = _.get(allVars, "stat_data", {});

    /* 路径字典平铺函数：将嵌套对象转换为单一深度映射 */
    const flatten = (obj, prefix = '', depth = 0) => {
        if (depth > 5) return {};
        return Object.entries(obj).reduce((acc, [k, v]) => {
            if (k.startsWith('_') || k.startsWith('$')) return acc;
            const path = prefix ? `${prefix}.${k}` : k;
            if (typeof v === 'object' && v !== null && !Array.isArray(v)) {
                Object.assign(acc, flatten(v, path, depth + 1));
            } else {
                acc[path] = v;
            }
            return acc;
        }, {});
    };

    /* 模块化分发逻辑 */
    const flatMap = flatten(rawData);
    const modules = {};

    Object.entries(flatMap).forEach(([path, val]) => {
        const rootKey = path.split('.')[0];
        if (!modules[rootKey]) modules[rootKey] = {};
        modules[rootKey][path.replace(`${rootKey}.`, '')] = val;
    });

    return modules;
}



/* === Step 6: 渲染函数 === */

async function drawHud(modules) {
    const $body = $('#hud-body');
    if (!$body.length) return;

    /* 使用 DocumentFragment 进行异步批量操作，防止频繁触发 Reflow */
    const fragment = document.createDocumentFragment();

    Object.entries(modules).forEach(([modName, dataset]) => {
        const $box = $('<div class="node-box"></div>');
        $box.append($('<div class="node-title"></div>').text(modName));

        Object.entries(dataset).forEach(([label, val]) => {
            const $row = $('<div class="data-row"></div>');
            $row.append($('<span class="data-label"></span>').text(label));

            const $valSpan = $('<span class="data-val"></span>');
            if (typeof val === 'number') {
                if (val >= 0 && val <= 100) {
                    const color = val > 80 ? 'var(--t-danger)' : 'var(--t-accent)';
                    $valSpan.html(`<div class="bar-frame"><div class="bar-core" style="width:${val}%; background:${color}"></div></div> <span style="margin-left:5px">${val}</span>`);
                } else { $valSpan.text(val).css('color', 'var(--t-accent)'); }
            } else if (typeof val === 'boolean') {
                $valSpan.text(val ? '▣ ACTIVE' : '□ INACTIVE').css('color', val ? 'var(--t-safe)' : 'var(--t-dim)');
            } else {
                $valSpan.text(val || 'N/A').css('color', 'var(--t-text)');
            }
            $row.append($valSpan);
            $box.append($row);
        });
        fragment.appendChild($box[0]);
    });

    $body[0].innerHTML = '';
    $body[0].appendChild(fragment);
    $('#hud-meta').text(`LAST_SYNC: ${new Date().toLocaleTimeString()} // SECTOR: ${_.get(modules, "世界.当前区域", "UNKNOWN")}`);
}



/* === Step 7: 事件绑定+入口 === */

async function bootSequence() {
    console.log("[HUD] 正在执行冷启动协议...");
    try {
        await waitGlobalInitialized('Mvu');
        const refresh = async () => {
            const data = await captureState();
            await drawHud(data);
        };

        /* 注册核心事件 */
        eventOn(Mvu.events.VARIABLE_INITIALIZED, refresh);
        eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, refresh);

        /* 执行首次渲染 */
        await refresh();

        /* 挂载自愈心跳：每 3 秒检测一次 DOM 状态 */
        const heartBeat = setInterval(() => {
            if (!$('#hud-mount').length) {
                console.warn("[HUD] 失去挂载点，正在回收内存...");
                clearInterval(heartBeat);
            }
        }, 3000);

    } catch (e) { 
        console.error("[HUD_CRITICAL_FAILURE]", e); 
        $('#hud-body').html('<div style="color:var(--t-danger); font-size:12px; padding:20px;">FATAL_ERROR: 神经链路映射中断。请尝试手动重置或检查变量结构。</div>');
    }
}

$(() => { setTimeout(bootSequence, 500); });
